import { Component, JSX } from "solid-js";

export const CardFrame: Component<JSX.HTMLAttributes<HTMLDivElement>> = (props) => {
	return (
		<div
			{...props}
			class={`card-frame-bg ${props.class}`}
			data-name="Card-Frame"
		>
			{props.children}
		</div>
	);
};

export const MetalCardFrame: Component<JSX.HTMLAttributes<HTMLDivElement>> = (props) => {
	return (
		<div
			{...props}
			class={`metal-card-frame-bg ${props.class}`}
			data-name="Metal-Card-Frame"
		>
			{props.children}
		</div>
	);
};
